@font-face {
  font-family: 'Bangers';
  src: url('./assets/fonts/bangers-latin.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #1b0d09;
  --bone: #f3dfb6;
  --bone-dim: #c6a980;
  --ember: #ff7a2f;
  --gold: #ffcf4d;
  --blood: #c43a2c;
  --stone: #38231b;
  --display: 'Bangers', 'Arial Black', Impact, sans-serif;
  --body: 'Trebuchet MS', 'Segoe UI', system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: #0b0706;
}

body {
  display: grid;
  place-items: center;
  min-height: 100dvh;
  padding: 18px;
  font-family: var(--body);
  color: var(--bone);
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 15%, rgba(197, 74, 32, 0.22), transparent 55%),
    radial-gradient(ellipse at 50% 110%, rgba(255, 145, 52, 0.10), transparent 58%),
    repeating-linear-gradient(115deg, rgba(255,255,255,0.014) 0 1px, transparent 1px 6px),
    #0b0706;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(255, 214, 155, 0.09) 0.6px, transparent 0.8px);
  background-size: 5px 5px;
  opacity: 0.5;
  mix-blend-mode: soft-light;
}

#shell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
}

#frame {
  position: relative;
  width: min(1180px, 96vw, calc(90vh * 16 / 9));
  aspect-ratio: 16 / 9;
  border-radius: 16px;
  overflow: hidden;
  background: #1a0e09;
  border: 2px solid #3b2418;
  box-shadow:
    0 0 0 5px #140c09,
    0 0 0 7px #4a2c1b,
    0 26px 70px rgba(0, 0, 0, 0.75),
    inset 0 0 70px rgba(0, 0, 0, 0.55);
  isolation: isolate;
}

canvas#game {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  background: #1a0e09;
}

.outside-hint {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #7c5f4a;
  text-align: center;
}
.outside-hint span { color: #a87f5e; }

/* ---------- overlay screens ---------- */

#overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  pointer-events: auto;
  opacity: 1;
  transition: opacity 220ms ease;
}

.screen.hidden {
  opacity: 0;
  pointer-events: none;
}

.screen-title {
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 3% 5%;
}

.title-scrim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 46%, rgba(14, 7, 5, 0.15) 0%, rgba(14, 7, 5, 0.62) 62%, rgba(14, 7, 5, 0.84) 100%),
    linear-gradient(180deg, rgba(17, 9, 7, 0.5), transparent 30%, transparent 68%, rgba(15, 8, 6, 0.72));
}

.title-lockup {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: translateY(-1%);
  animation: rise-in 700ms cubic-bezier(.16,1,.3,1) both;
}

.eyebrow {
  margin: 0 0 0.2em;
  font-family: var(--body);
  font-weight: 800;
  font-size: clamp(9px, 1.1vw, 14px);
  letter-spacing: 0.44em;
  color: #ffc47d;
  text-shadow: 0 2px 0 rgba(0,0,0,0.65);
}
.eyebrow span { color: #ff7a2f; }

.logo {
  position: relative;
  margin: 0;
  font-family: var(--display);
  font-size: clamp(76px, 15.5vw, 196px);
  line-height: 0.72;
  letter-spacing: 0.015em;
  color: #ffcf4d;
  -webkit-text-stroke: clamp(2px, 0.35vw, 5px) #2a130b;
  paint-order: stroke fill;
  text-shadow:
    0 clamp(3px, 0.5vw, 7px) 0 #a3481c,
    0 clamp(7px, 1.05vw, 15px) 0 #572412,
    0 clamp(11px, 1.6vw, 23px) 10px rgba(0, 0, 0, 0.55),
    0 0 46px rgba(255, 154, 55, 0.35);
  transform: rotate(-2.2deg);
  animation: logo-bob 3.6s ease-in-out infinite;
}
.logo-bang {
  display: inline-block;
  color: #ff5b2e;
  transform: rotate(6deg) translateY(-0.06em);
  -webkit-text-stroke-color: #2a130b;
  text-shadow:
    0 clamp(3px, 0.5vw, 7px) 0 #7d230f,
    0 clamp(7px, 1.05vw, 15px) 0 #451208,
    0 0 34px rgba(255, 91, 46, 0.55);
}

.tagline {
  margin: 0.45em 0 1.25em;
  font-family: var(--display);
  font-size: clamp(14px, 2.05vw, 28px);
  letter-spacing: 0.2em;
  color: #f3dfb6;
  text-shadow: 0 2px 0 #2a130b, 0 4px 8px rgba(0,0,0,0.7);
  transform: rotate(-0.6deg);
}

.bone-btn {
  position: relative;
  appearance: none;
  border: 0;
  cursor: pointer;
  padding: 0.86em 1.9em 0.78em;
  border-radius: 10px 14px 10px 12px;
  font-family: var(--display);
  font-size: clamp(17px, 2vw, 29px);
  letter-spacing: 0.1em;
  color: #2b130b;
  background:
    linear-gradient(180deg, #ffe8b0 0%, #f3cf85 47%, #dbaa5b 100%);
  box-shadow:
    inset 0 2px 0 rgba(255, 255, 255, 0.75),
    inset 0 -3px 0 rgba(107, 59, 23, 0.45),
    0 6px 0 #63351a,
    0 10px 22px rgba(0, 0, 0, 0.5);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.45);
  transform: rotate(-0.8deg);
  transition: transform 90ms ease, box-shadow 90ms ease, filter 120ms ease;
}
.bone-btn::before,
.bone-btn::after {
  content: '';
  position: absolute;
  top: 50%;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #f6d896;
  border: 2px solid #4b2a13;
  transform: translateY(-50%);
  box-shadow: inset -2px -2px 0 rgba(107, 59, 23, 0.35);
