.bone-btn:hover { filter: brightness(1.08); transform: rotate(-0.8deg) translateY(-2px); }
.bone-btn:active {
  transform: rotate(-0.8deg) translateY(4px);
  box-shadow: inset 0 2px 0 rgba(255,255,255,.6), inset 0 -2px 0 rgba(107,59,23,.4), 0 2px 0 #63351a, 0 5px 12px rgba(0,0,0,.5);
}
.bone-btn:focus-visible { outline: 3px solid #ff7a2f; outline-offset: 5px; }
.bone-btn.small { font-size: clamp(15px, 1.6vw, 23px); padding: 0.8em 1.5em 0.72em; }

.control-row {
  display: flex;
  gap: clamp(8px, 1.6vw, 22px);
  align-items: stretch;
  margin-top: clamp(16px, 2.8vw, 34px);
  padding: 8px 14px;
  border-radius: 12px;
  background: rgba(27, 13, 9, 0.58);
  border: 1px solid rgba(243, 223, 182, 0.16);
  box-shadow: 0 4px 20px rgba(0,0,0,.3);
}
.control {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: clamp(8px, 0.9vw, 12px);
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #d7b88c;
}
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 1.9em;
  padding: 0.25em 0.4em 0.2em;
  border-radius: 5px;
  background: #f3dfb6;
  color: #2a130b;
  font-family: var(--body);
  font-weight: 900;
  font-size: 0.95em;
  letter-spacing: 0;
  box-shadow: 0 2px 0 #7a4a26, inset 0 -1px 0 rgba(0,0,0,.2);
}

.hint {
  margin: clamp(12px, 2vw, 24px) 0 0;
  font-size: clamp(9px, 1vw, 13px);
  line-height: 1.55;
  letter-spacing: 0.1em;
  color: #a98a6b;
  text-transform: uppercase;
}

.corner-note,
.version-note {
  position: absolute;
  z-index: 2;
  bottom: 18px;
  font-size: clamp(8px, 0.9vw, 12px);
  letter-spacing: 0.2em;
  color: #c5a37d;
  text-transform: uppercase;
}
.corner-note { left: 24px; }
.corner-note span { color: #ffcf4d; font-weight: 800; }
.version-note { right: 24px; color: #84674f; }

.screen-center {
  align-items: center;
  justify-content: center;
  background: rgba(10, 5, 4, 0.66);
  backdrop-filter: blur(3px);
}

.stone-panel {
  position: relative;
  width: min(480px, 78%);
  padding: clamp(22px, 3.6vw, 46px) clamp(22px, 4vw, 54px);
  text-align: center;
  background:
    radial-gradient(circle at 30% 12%, rgba(255, 181, 96, 0.13), transparent 40%),
    repeating-linear-gradient(102deg, rgba(255,255,255,0.022) 0 2px, transparent 2px 11px),
