  border: 2px solid #8b603c;
  box-shadow: inset 0 1px 2px #000;
}
.stone-panel::before { top: 11px; left: 12px; }
.stone-panel::after { top: 11px; right: 12px; }

.kicker {
  margin: 0 0 0.4em;
  font-size: clamp(8px, 0.95vw, 12px);
  font-weight: 800;
  letter-spacing: 0.3em;
  color: #d99a5b;
  text-transform: uppercase;
}

.panel-title {
  margin: 0 0 0.35em;
  font-family: var(--display);
  font-size: clamp(42px, 6.4vw, 84px);
