const KEYMAP = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  KeyJ: 'attack', KeyX: 'attack',
  KeyK: 'jump', KeyZ: 'jump', Space: 'jump',
  KeyL: 'special', KeyC: 'special',
  Enter: 'confirm', NumpadEnter: 'confirm',
  KeyP: 'pause', Escape: 'pause',
  KeyM: 'mute', KeyR: 'restart',
}

export class Input {
  constructor() {
    this.held = new Set()
    this.pressed = new Set()
    this.ax = 0
    this.az = 0
    this.joy = { x: 0, y: 0, active: false }
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window

    addEventListener('keydown', (event) => {
      const action = KEYMAP[event.code]
      if (!action) return
      if (['left', 'right', 'up', 'down', 'attack', 'jump', 'special', 'confirm', 'pause'].includes(action)) {
        event.preventDefault()
      }
      if (!event.repeat) this.pressed.add(action)
      this.held.add(action)
    }, { passive: false })

    addEventListener('keyup', (event) => {
      const action = KEYMAP[event.code]
      if (!action) return
      this.held.delete(action)
      if (['left', 'right', 'up', 'down', 'attack', 'jump', 'special'].includes(action)) event.preventDefault()
    }, { passive: false })

    addEventListener('blur', () => {
      this.held.clear()
      this.joy.x = 0
      this.joy.y = 0
      this.joy.active = false
    })

    if (this.isTouch) document.body.classList.add('touch')
    this.setupJoystick()
    this.setupButtons()
  }

  setupJoystick() {
    const base = document.getElementById('joystick')
    const knob = document.getElementById('stick-knob')
    if (!base || !knob) return
    let pointerId = null
    const max = 36

    const move = (event) => {
      const rect = base.getBoundingClientRect()
      const cx = rect.left + rect.width / 2
      const cy = rect.top + rect.height / 2
      let dx = event.clientX - cx
      let dy = event.clientY - cy
      const len = Math.hypot(dx, dy) || 1
      const clamped = Math.min(len, max)
      dx = (dx / len) * clamped
      dy = (dy / len) * clamped
      knob.style.transform = `translate(${dx}px, ${dy}px)`
      const nx = dx / max
      const ny = dy / max
      const dead = 0.16
      this.joy.x = Math.abs(nx) < dead ? 0 : nx
      this.joy.y = Math.abs(ny) < dead ? 0 : ny
      this.joy.active = true
    }

    base.addEventListener('pointerdown', (event) => {
      pointerId = event.pointerId
      base.setPointerCapture(pointerId)
      move(event)
      event.preventDefault()
    })
    base.addEventListener('pointermove', (event) => {
      if (event.pointerId !== pointerId) return
      move(event)
      event.preventDefault()
    })
    const end = (event) => {
      if (pointerId !== null && event.pointerId !== pointerId) return
      pointerId = null
      this.joy.x = 0
      this.joy.y = 0
      this.joy.active = false
      knob.style.transform = 'translate(0px, 0px)'
    }
    base.addEventListener('pointerup', end)
    base.addEventListener('pointercancel', end)
    base.addEventListener('lostpointercapture', end)
  }

  setupButtons() {
    for (const button of document.querySelectorAll('.touch-btn')) {
      const action = button.dataset.action
      button.addEventListener('pointerdown', (event) => {
        event.preventDefault()
        this.pressed.add(action)
        this.held.add(action)
        button.classList.add('pressed')
      })
      const release = (event) => {
        event.preventDefault()
        this.held.delete(action)
        button.classList.remove('pressed')
      }
      button.addEventListener('pointerup', release)
      button.addEventListener('pointercancel', release)
      button.addEventListener('pointerleave', release)
    }
  }

  sample() {
    let x = (this.held.has('right') ? 1 : 0) - (this.held.has('left') ? 1 : 0)
    let z = (this.held.has('down') ? 1 : 0) - (this.held.has('up') ? 1 : 0)
    if (this.joy.active) {
      x = this.joy.x
      z = this.joy.y
    }
    const len = Math.hypot(x, z)
    if (len > 1) {
      x /= len
      z /= len
    }
    this.ax = x
    this.az = z
  }

  consume(action) {
    if (!this.pressed.has(action)) return false
    this.pressed.delete(action)
    return true
  }

  isDown(action) {
    return this.held.has(action)
  }

  endFrame() {
    this.pressed.clear()
  }
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicBus = null
    this.sfxBus = null
    this.muted = false
    this.scene = 'title'
    this.step = 0
    this.nextNote = 0
    this.timer = null
    this.noise = null
    this.lastStepAt = 0
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AudioContextClass = window.AudioContext || window.webkitAudioContext
    if (!AudioContextClass) return
    const ctx = new AudioContextClass()
    this.ctx = ctx

    const compressor = ctx.createDynamicsCompressor()
    compressor.threshold.value = -18
    compressor.knee.value = 22
    compressor.ratio.value = 8
    compressor.attack.value = 0.004
    compressor.release.value = 0.24
    compressor.connect(ctx.destination)

    this.master = ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.66
    this.master.connect(compressor)

    this.musicBus = ctx.createGain()
    this.musicBus.gain.value = 0
    this.musicBus.connect(this.master)

    this.sfxBus = ctx.createGain()
    this.sfxBus.gain.value = 0.52
    this.sfxBus.connect(this.master)

    this.noise = this.createNoiseBuffer(1.2)
    this.nextNote = ctx.currentTime + 0.06
    this.timer = setInterval(() => this.schedule(), 30)
    this.schedule()
    this.musicBus.gain.setTargetAtTime(0.16, ctx.currentTime, 0.8)
  }

  createNoiseBuffer(seconds) {
    const ctx = this.ctx
    const length = Math.floor(ctx.sampleRate * seconds)
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      data[i] = last * 3.2
    }
    return buffer
  }

  setScene(scene) {
    if (this.scene === scene) return
    this.scene = scene
    this.step = 0
    if (this.ctx) this.nextNote = this.ctx.currentTime + 0.04
  }

  toggleMute(force) {
    this.muted = typeof force === 'boolean' ? force : !this.muted
    if (this.ctx) {
      const now = this.ctx.currentTime
      this.master.gain.cancelScheduledValues(now)
      this.master.gain.setTargetAtTime(this.muted ? 0 : 0.66, now, 0.04)
    }
    return this.muted
  }

  tempo() {
    if (this.scene === 'boss') return 132
    if (this.scene === 'fight') return 112
    return 86
  }

  schedule() {
    const ctx = this.ctx
    if (!ctx || ctx.state !== 'running') return
    const stepDur = 60 / this.tempo() / 4
    const horizon = ctx.currentTime + 0.16
    let guard = 0
    while (this.nextNote < horizon && guard < 24) {
      this.playStep(this.step, this.nextNote)
      this.nextNote += stepDur
      this.step = (this.step + 1) % 128
      guard += 1
    }
  }

  playStep(step, time) {
    const bar = Math.floor(step / 16)
    const beat = step % 16
    const fight = this.scene === 'fight' || this.scene === 'boss'
    const boss = this.scene === 'boss'

    if (!fight) {
      if (beat === 0 || beat === 8) this.kick(time, 0.22)
      if (beat === 4 || beat === 12) this.shaker(time, 0.035)
      if (bar % 2 === 0 && (beat === 0 || beat === 8)) {
        this.drone(time, 55 * (bar % 4 === 2 ? 1.2 : 1), 1.35, 0.022)
      }
      if (bar % 2 === 1 && (beat === 2 || beat === 10)) {
        this.flute(time, [330, 392, 440, 392, 330][bar % 5], 0.55, 0.026)
      }
      return
    }

    if (beat === 0 || beat === 6 || (boss && beat === 10)) this.kick(time, 0.34)
    if (beat === 8 || beat === 14 || (boss && beat === 3)) this.kick(time, 0.26)
    if (beat === 3 || beat === 11 || (boss && beat === 15)) this.tom(time, beat === 11 ? 120 : 90, 0.18)
    if (beat % 2 === 1) this.shaker(time, 0.045)
    if (beat === 0 || beat === 8) {
      this.drone(time, [55, 55, 65.4, 49][bar % 4], 0.45, 0.05)
    }
    if (beat === 0 && bar % 4 === 0) {
      const melody = [220, 261.63, 293.66, 329.63, 293.66, 261.63, 220, 196][Math.floor(step / 16) % 8]
      this.flute(time + 0.1, melody, 0.5, 0.022)
    }
    if (boss && beat === 4 && bar % 2 === 0) {
      this.flute(time, 146.83, 0.32, 0.02)
    }
  }

  tone(time, freq, endFreq, duration, type, peak, filter) {
    const ctx = this.ctx
    if (!ctx) return
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(Math.max(20, freq), time)
    if (endFreq && endFreq !== freq) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), time + duration)
    }
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), time + Math.min(0.012, duration * 0.2))
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    let node = gain
    if (filter) {
      const biquad = ctx.createBiquadFilter()
      biquad.type = filter.type || 'lowpass'
      biquad.frequency.value = filter.freq || 900
      biquad.Q.value = filter.q ?? 0.7
      gain.connect(biquad)
      node = biquad
    }
    osc.connect(gain)
    node.connect(this.sfxBus)
    osc.start(time)
    osc.stop(time + duration + 0.02)
  }

  noiseBurst(time, duration, peak, filterType, freq, q = 0.8, endFreq) {
    const ctx = this.ctx
    if (!ctx || !this.noise) return
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    const gain = ctx.createGain()
    const filter = ctx.createBiquadFilter()
    filter.type = filterType
    filter.frequency.setValueAtTime(freq, time)
    if (endFreq) filter.frequency.exponentialRampToValueAtTime(Math.max(40, endFreq), time + duration)
    filter.Q.value = q
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), time + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.sfxBus)
    src.start(time, Math.random() * 0.3, duration + 0.02)
  }

  kick(time, peak = 0.3) {
    const ctx = this.ctx
    if (!ctx) return
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(130, time)
    osc.frequency.exponentialRampToValueAtTime(48, time + 0.14)
    gain.gain.setValueAtTime(peak, time)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.2)
    osc.connect(gain)
    gain.connect(this.musicBus)
    osc.start(time)
    osc.stop(time + 0.22)
  }

  tom(time, freq, peak) {
    const ctx = this.ctx
    if (!ctx) return
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = 'triangle'
    osc.frequency.setValueAtTime(freq * 1.35, time)
    osc.frequency.exponentialRampToValueAtTime(freq, time + 0.09)
    gain.gain.setValueAtTime(peak, time)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.24)
    osc.connect(gain)
    gain.connect(this.musicBus)
    osc.start(time)
    osc.stop(time + 0.26)
  }

  shaker(time, peak) {
    if (!this.ctx || !this.noise) return
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'highpass'
    filter.frequency.value = 5200
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(peak, time)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.055)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.musicBus)
    src.start(time, Math.random() * 0.5, 0.06)
  }

  drone(time, freq, duration, peak) {
    const ctx = this.ctx
    if (!ctx) return
    const osc = ctx.createOscillator()
    const osc2 = ctx.createOscillator()
    const filter = ctx.createBiquadFilter()
    const gain = ctx.createGain()
    osc.type = 'sawtooth'
    osc2.type = 'sine'
    osc.frequency.value = freq
    osc2.frequency.value = freq * 2.005
    filter.type = 'lowpass'
    filter.frequency.value = 320
    filter.Q.value = 4
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.exponentialRampToValueAtTime(peak, time + 0.06)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    osc.connect(filter)
    osc2.connect(filter)
    filter.connect(gain)
    gain.connect(this.musicBus)
    osc.start(time)
    osc2.start(time)
    osc.stop(time + duration + 0.05)
    osc2.stop(time + duration + 0.05)
  }

  flute(time, freq, duration, peak) {
    const ctx = this.ctx
    if (!ctx) return
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    const lfo = ctx.createOscillator()
    const lfoGain = ctx.createGain()
    osc.type = 'sine'
    osc.frequency.value = freq
    lfo.frequency.value = 5.2
    lfoGain.gain.value = 4.5
    lfo.connect(lfoGain)
    lfoGain.connect(osc.frequency)
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.exponentialRampToValueAtTime(peak, time + 0.06)
    gain.gain.exponentialRampToValueAtTime(peak * 0.7, time + duration * 0.6)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    osc.connect(gain)
    gain.connect(this.musicBus)
    osc.start(time)
    lfo.start(time)
    osc.stop(time + duration + 0.02)
    lfo.stop(time + duration + 0.02)
  }

  sfx(name) {
    if (!this.ctx || this.ctx.state !== 'running') return
    const t = this.ctx.currentTime + 0.001
    switch (name) {
      case 'swing':
        this.noiseBurst(t, 0.13, 0.13, 'bandpass', 1300, 1.4, 420)
        break
      case 'hit':
        this.tone(t, 155, 62, 0.14, 'triangle', 0.35, { type: 'lowpass', freq: 900 })
        this.noiseBurst(t, 0.09, 0.18, 'bandpass', 900, 1, 300)
        break
      case 'heavy':
        this.tone(t, 120, 38, 0.24, 'sine', 0.5)
        this.noiseBurst(t, 0.16, 0.24, 'lowpass', 700, 0.8, 180)
        break
      case 'hurt':
        this.tone(t, 240, 80, 0.26, 'sawtooth', 0.2, { type: 'lowpass', freq: 1200 })
        break
      case 'jump':
        this.tone(t, 210, 390, 0.13, 'sine', 0.14)
        break
      case 'land':
        this.noiseBurst(t, 0.11, 0.16, 'lowpass', 480, 0.7, 120)
        break
      case 'roar':
        this.tone(t, 92, 42, 0.8, 'sawtooth', 0.32, { type: 'lowpass', freq: 480, q: 3 })
        this.noiseBurst(t, 0.75, 0.16, 'lowpass', 600, 2, 160)
        break
      case 'special':
        this.tone(t, 70, 34, 0.85, 'sawtooth', 0.34, { type: 'lowpass', freq: 520, q: 5 })
        this.noiseBurst(t, 0.55, 0.2, 'bandpass', 400, 1.1, 110)
        break
      case 'meat':
        this.tone(t, 440, 440, 0.1, 'sine', 0.14)
        this.tone(t + 0.08, 660, 660, 0.14, 'sine', 0.12)
        break
      case 'clear':
        this.tone(t, 392, 392, 0.16, 'triangle', 0.14)
        this.tone(t + 0.14, 523.25, 523.25, 0.3, 'triangle', 0.14)
        break
      case 'gameover':
        this.tone(t, 196, 196, 0.3, 'sawtooth', 0.13, { type: 'lowpass', freq: 900 })
        this.tone(t + 0.24, 155, 155, 0.45, 'sawtooth', 0.12, { type: 'lowpass', freq: 700 })
        this.tone(t + 0.55, 110, 82, 0.9, 'sawtooth', 0.12, { type: 'lowpass', freq: 500 })
        break
      case 'win':
        [523.25, 659.25, 783.99, 1046.5].forEach((freq, index) => {
          this.tone(t + index * 0.12, freq, freq, 0.28, 'triangle', 0.13)
        })
        break
      case 'charge':
        this.noiseBurst(t, 0.6, 0.13, 'bandpass', 220, 0.8, 900)
        break
      case 'slam':
        this.tone(t, 84, 28, 0.5, 'sine', 0.55)
        this.noiseBurst(t, 0.4, 0.25, 'lowpass', 500, 0.7, 80)
        break
      default:
        break
    }
  }

  stop() {
    if (this.timer) clearInterval(this.timer)
    this.timer = null
    if (this.ctx) this.ctx.close()
    this.ctx = null
  }
}

import { VIEW_W, GROUND_TOP, DEPTH, GRAVITY } from './config.js'

const DISPLAY = '"Bangers", "Arial Black", Impact, sans-serif'

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function rand(min, max) {
  return min + Math.random() * (max - min)
}

function easeOut(step) {
  return 1 - Math.pow(1 - step, 3)
}

function screenPosition(entity, cameraX) {
  return {
    x: entity.x - cameraX,
    y: GROUND_TOP + entity.z * DEPTH - (entity.y || 0),
  }
}

export class FX {
  constructor() {
    this.particles = []
    this.rings = []
    this.texts = []
  }

  reset() {
    this.particles.length = 0
    this.rings.length = 0
    this.texts.length = 0
  }

  dust(x, z, count = 6, options = {}) {
    const color = options.color || '210, 170, 120'
    for (let i = 0; i < count; i += 1) {
      this.particles.push({
        type: 'dust',
        x: x + rand(-12, 12),
        z: clamp(z + rand(-0.02, 0.02), 0, 1),
        y: rand(0, 5),
        vx: rand(-42, 42),
        vy: rand(10, 46),
        vz: rand(-0.035, 0.035),
        life: rand(0.3, 0.62),
        maxLife: 0.62,
        size: rand(3, 9),
        color,
        gravity: -6,
        alpha: 0.5,
      })
    }
  }

  impact(x, z, height = 52, strength = 1, color = '255, 205, 95') {
    for (let i = 0; i < 7 + strength * 4; i += 1) {
      const angle = rand(0, Math.PI * 2)
      const speed = rand(90, 260) * strength
      this.particles.push({
        type: Math.random() > 0.62 ? 'star' : 'spark',
        x,
        z,
        y: height + rand(-10, 10),
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed * 0.8 + 70,
        vz: rand(-0.04, 0.04),
        life: rand(0.16, 0.38),
        maxLife: 0.38,
        size: rand(4, 11) * Math.min(1.5, strength),
        color,
        gravity: GRAVITY * 0.7,
        rot: rand(0, Math.PI),
        vr: rand(-12, 12),
        alpha: 1,
      })
    }
  }

  bones(x, z, height = 20, count = 4) {
    for (let i = 0; i < count; i += 1) {
      this.particles.push({
        type: 'bone',
        x,
        z,
        y: height + rand(0, 25),
        vx: rand(-170, 170),
        vy: rand(100, 280),
        vz: rand(-0.05, 0.05),
        life: rand(0.5, 0.9),
        maxLife: 0.9,
        size: rand(4, 7),
        color: '236, 219, 184',
        gravity: GRAVITY,
        rot: rand(0, Math.PI * 2),
        vr: rand(-14, 14),
        alpha: 1,
      })
    }
  }

  slash(x, z, dir, height = 52, size = 46) {
    this.particles.push({
      type: 'slash',
      x,
      z,
      y: height,
      vx: 0,
      vy: 0,
      vz: 0,
      life: 0.14,
      maxLife: 0.14,
      size,
      color: '255, 235, 170',
      dir,
      alpha: 1,
    })
  }

  debris(x, z, y, count = 5) {
    for (let i = 0; i < count; i += 1) {
      this.particles.push({
        type: 'debris',
        x,
        z,
        y,
        vx: rand(-140, 140),
        vy: rand(80, 240),
        vz: rand(-0.03, 0.03),
        life: rand(0.35, 0.7),
        maxLife: 0.7,
        size: rand(2, 5),
        color: '117, 76, 50',
        gravity: GRAVITY,
        rot: rand(0, Math.PI),
        vr: rand(-9, 9),
        alpha: 1,
      })
    }
  }

  ring(x, z, maxRadius, color = '255, 207, 93', duration = 0.45, width = 0.26) {
    this.rings.push({
      x,
      z,
      maxRadius,
      radius: 0,
      color,
      duration,
      life: duration,
      width,
    })
  }

  text(text, x, z, color = '#ffcf4d', size = 20, options = {}) {
    this.texts.push({
      text,
      x,
      z,
      y: options.height ?? 86,
      vy: options.vy ?? 48,
      life: options.life ?? 0.8,
      maxLife: options.life ?? 0.8,
      color,
      size,
      stroke: options.stroke || '#24110b',
      rotation: options.rotation ?? rand(-0.06, 0.06),
      alpha: 1,
    })
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i -= 1) {
      const particle = this.particles[i]
      particle.life -= dt
      if (particle.life <= 0) {
        this.particles.splice(i, 1)
        continue
      }
      if (particle.type === 'slash') continue
      particle.x += particle.vx * dt
      particle.z = clamp(particle.z + particle.vz * dt, 0, 1)
      particle.y += particle.vy * dt
      particle.vy -= (particle.gravity || 0) * dt
      if (particle.rot !== undefined) particle.rot += (particle.vr || 0) * dt
      if (particle.y < 0) {
        particle.y = 0
        particle.vy *= -0.28
        particle.vx *= 0.7
      }
    }

    for (let i = this.rings.length - 1; i >= 0; i -= 1) {
      const ring = this.rings[i]
      ring.life -= dt
      if (ring.life <= 0) this.rings.splice(i, 1)
    }

    for (let i = this.texts.length - 1; i >= 0; i -= 1) {
      const text = this.texts[i]
      text.life -= dt
      text.y += text.vy * dt
      text.vy *= 0.94
      if (text.life <= 0) this.texts.splice(i, 1)
    }
  }

  drawGround(ctx, cameraX) {
    for (const ring of this.rings) {
      const progress = 1 - ring.life / ring.duration
      const radius = ring.maxRadius * easeOut(progress)
      const alpha = Math.max(0, 1 - progress)
      const x = ring.x - cameraX
      const y = GROUND_TOP + ring.z * DEPTH
      if (x < -radius - 40 || x > VIEW_W + radius + 40) continue

      ctx.save()
      ctx.globalAlpha = alpha * 0.9
      ctx.strokeStyle = `rgba(${ring.color}, 0.9)`
      ctx.lineWidth = 7 * (1 - progress) + 1.5
      ctx.beginPath()
      ctx.ellipse(x, y, radius, radius * ring.width, 0, 0, Math.PI * 2)
      ctx.stroke()
      ctx.globalAlpha = alpha * 0.24
      ctx.strokeStyle = `rgba(${ring.color}, 0.8)`
      ctx.lineWidth = 15 * (1 - progress) + 2
      ctx.stroke()
      if (progress < 0.3) {
        ctx.globalAlpha = (1 - progress / 0.3) * 0.18
        ctx.fillStyle = `rgba(${ring.color}, 0.8)`
        ctx.beginPath()
        ctx.ellipse(x, y, radius, radius * ring.width, 0, 0, Math.PI * 2)
        ctx.fill()
      }
      ctx.restore()
    }
  }

  draw(ctx, cameraX) {
    for (const particle of this.particles) {
      const alpha = clamp(particle.life / Math.max(0.001, particle.maxLife), 0, 1)
      const x = particle.x - cameraX
      const y = GROUND_TOP + particle.z * DEPTH - particle.y
      if (x < -80 || x > VIEW_W + 80) continue

      ctx.save()
      ctx.globalAlpha = alpha * (particle.alpha ?? 1)

      if (particle.type === 'dust') {
        const growth = 1 + (1 - alpha) * 1.6
        ctx.fillStyle = `rgba(${particle.color}, 0.5)`
        ctx.beginPath()
        ctx.arc(x, y, particle.size * growth, 0, Math.PI * 2)
        ctx.fill()
      } else if (particle.type === 'spark') {
        const speed = Math.hypot(particle.vx, particle.vy)
        const angle = Math.atan2(particle.vy, particle.vx)
        ctx.strokeStyle = `rgba(${particle.color}, 0.95)`
        ctx.lineWidth = 2.5
        ctx.lineCap = 'round'
        ctx.beginPath()
        ctx.moveTo(x, y)
        ctx.lineTo(x - Math.cos(angle) * Math.min(18, speed * 0.06), y + Math.sin(angle) * Math.min(18, speed * 0.06))
        ctx.stroke()
        ctx.fillStyle = `rgba(255, 250, 220, ${alpha})`
        ctx.beginPath()
        ctx.arc(x, y, 2.2, 0, Math.PI * 2)
        ctx.fill()
      } else if (particle.type === 'star') {
        ctx.translate(x, y)
        ctx.rotate(particle.rot)
        ctx.fillStyle = `rgba(${particle.color}, 0.95)`
        ctx.strokeStyle = 'rgba(39, 19, 12, 0.7)'
        ctx.lineWidth = 1
        ctx.beginPath()
        for (let i = 0; i < 8; i += 1) {
          const angle = (i / 8) * Math.PI * 2
          const radius = i % 2 === 0 ? particle.size : particle.size * 0.35
          const px = Math.cos(angle) * radius
          const py = Math.sin(angle) * radius
          if (i === 0) ctx.moveTo(px, py)
          else ctx.lineTo(px, py)
        }
        ctx.closePath()
        ctx.fill()
        ctx.stroke()
      } else if (particle.type === 'bone') {
        ctx.translate(x, y)
        ctx.rotate(particle.rot)
        ctx.strokeStyle = 'rgba(236, 219, 184, 0.95)'
        ctx.lineWidth = particle.size * 0.55
        ctx.lineCap = 'round'
        ctx.beginPath()
        ctx.moveTo(-particle.size, 0)
        ctx.lineTo(particle.size, 0)
        ctx.stroke()
        ctx.fillStyle = 'rgba(236, 219, 184, 0.95)'
        ctx.beginPath()
        ctx.arc(-particle.size, -particle.size * 0.4, particle.size * 0.45, 0, Math.PI * 2)
        ctx.arc(-particle.size, particle.size * 0.4, particle.size * 0.45, 0, Math.PI * 2)
        ctx.arc(particle.size, -particle.size * 0.4, particle.size * 0.45, 0, Math.PI * 2)
        ctx.arc(particle.size, particle.size * 0.4, particle.size * 0.45, 0, Math.PI * 2)
        ctx.fill()
      } else if (particle.type === 'slash') {
        const progress = 1 - alpha
        const start = particle.dir > 0 ? -1.35 : Math.PI - 1.35
        const end = particle.dir > 0 ? 1.35 : Math.PI + 1.35
        ctx.translate(x, y)
        ctx.rotate(-0.15 + progress * 0.3)
        ctx.strokeStyle = `rgba(${particle.color}, ${0.85 * alpha})`
        ctx.lineWidth = 8 * alpha + 2
        ctx.lineCap = 'round'
        ctx.beginPath()
        ctx.arc(0, 0, particle.size, start, end)
        ctx.stroke()
        ctx.strokeStyle = `rgba(255, 255, 235, ${0.8 * alpha})`
        ctx.lineWidth = 2.5 * alpha + 0.5
        ctx.beginPath()
        ctx.arc(0, 0, particle.size - 3, start + 0.08, end - 0.08)
        ctx.stroke()
      } else if (particle.type === 'debris') {
        ctx.translate(x, y)
        ctx.rotate(particle.rot)
        ctx.fillStyle = `rgba(${particle.color}, 0.95)`
        ctx.fillRect(-particle.size / 2, -particle.size / 2, particle.size, particle.size * 0.8)
      }
      ctx.restore()
    }

    for (const text of this.texts) {
      const alpha = clamp(text.life / text.maxLife, 0, 1)
      const age = 1 - alpha
      const pop = 1 + Math.max(0, 0.26 - age) * 2.4
      const x = text.x - cameraX
      const y = GROUND_TOP + text.z * DEPTH - text.y
      if (x < -120 || x > VIEW_W + 120) continue
      ctx.save()
      ctx.globalAlpha = Math.min(1, alpha * 1.8)
      ctx.translate(x, y)
      ctx.rotate(text.rotation)
      ctx.scale(pop, pop)
      ctx.font = `400 ${text.size}px ${DISPLAY}`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.lineJoin = 'round'
      ctx.lineWidth = Math.max(2, text.size * 0.16)
      ctx.strokeStyle = text.stroke
      ctx.strokeText(text.text, 0, 0)
      ctx.fillStyle = text.color
      ctx.fillText(text.text, 0, 0)
      ctx.restore()
    }
  }
}

import {
  ATTACKS, ENEMY_STATS, GRAVITY, JUMP_SPEED, LEVEL_END,
  PLAYER_SPEED, PLAYER_Z_SPEED, VIEW_W,
} from './config.js'

const COMBO_WORDS = ['BONK!', 'WHACK!', 'THWUMP!', 'CRUNCH!', 'SMACK!', 'OOF!']

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function rand(min, max) {
  return min + Math.random() * (max - min)
}

function comboMultiplier(combo) {
  return 1 + Math.min(2, Math.floor(combo / 5) * 0.5)
}

function pickWord() {
  return COMBO_WORDS[Math.floor(Math.random() * COMBO_WORDS.length)]
}

export function createPlayer() {
  return {
    kind: 'player',
    x: 190,
    z: 0.62,
    jumpY: 0,
    vy: 0,
    vx: 0,
    vz: 0,
    facing: 1,
    hp: 100,
    maxHp: 100,
    hpGhost: 100,
    lives: 3,
    special: 0,
    state: 'idle',
    stateT: 0,
    animT: 0,
    attackT: 0,
    attackP: 0,
    attackDur: 0,
    comboStep: 0,
    didHit: false,
    attackBuffer: 0,
    iframes: 0,
    hitFlash: 0,
    downP: 0,
    downTimer: 0,
    stepTimer: 0,
    scale: 1,
    seed: 3.7,
    alpha: 1,
  }
}

export function createEnemy(type, x, z, slot = 0) {
  const stats = ENEMY_STATS[type]
  return {
    kind: type,
    x,
    z,
    jumpY: 0,
    vy: 0,
    vx: 0,
    vz: 0,
    facing: -1,
    hp: stats.hp,
    maxHp: stats.hp,
    hpGhost: stats.hp,
    speed: stats.speed,
    damage: stats.damage,
    range: stats.range,
    attackDuration: stats.attackDuration || 1,
    hitAt: stats.hitAt || 0.54,
    attackCooldown: rand(0.45, 1.1),
    state: 'spawn',
    stateT: 0,
    animT: rand(0, 3),
    attackT: 0,
    attackP: 0,
    didHit: false,
    slotOffset: type === 'boss' ? 0 : ((slot % 3) - 1) * 0.11,
    scoreValue: stats.score,
    scale: stats.scale,
    seed: rand(0, 10),
    hitFlash: 0,
    dead: false,
    deadT: 0,
    downP: 0,
    alpha: 1,
    stepTimer: 0,
    enraged: false,
    pattern: 0,
    slamTarget: null,
    slamFrom: null,
    leapFrom: null,
    leapTo: null,
  }
}

/* ------------------------------------------------------------------ */
/* Player                                                              */
/* ------------------------------------------------------------------ */

function playerBounds(game, player) {
  player.z = clamp(player.z, 0, 1)
  const minX = game.camera.x + 32
  const maxX = Math.min(game.camera.x + VIEW_W - 36, LEVEL_END - 36)
  player.x = clamp(player.x, minX, maxX)
}

function startAttack(game, step) {
  const player = game.player
  const attack = ATTACKS[step]
  player.state = 'attack'
  player.stateT = 0
  player.attackT = 0
  player.attackP = 0
  player.attackDur = attack.duration
  player.comboStep = step
  player.didHit = false
  player.attackBuffer = 0
  game.audio.sfx('swing')
}

function startSpecial(game) {
  const player = game.player
  player.state = 'special'
  player.stateT = 0
  player.attackP = 0
  player.didBlast = false
  player.iframes = Math.max(player.iframes, 1.15)
  player.special = 0
  game.shake = Math.max(game.shake, 5)
}

function playerHitCheck(game) {
  const player = game.player
  const attack = ATTACKS[player.comboStep] || ATTACKS[0]
  let hitAny = false
  for (const enemy of game.enemies) {
    if (enemy.dead) continue
    const dx = (enemy.x - player.x) * player.facing
    const depth = Math.abs(enemy.z - player.z)
    const bossBonus = enemy.kind === 'boss' ? 30 : 0
    if (dx > -20 && dx < attack.range + bossBonus && depth < attack.depth + (enemy.kind === 'boss' ? 0.12 : 0)) {
      damageEnemy(game, enemy, attack.damage, attack.knock, player.facing)
      hitAny = true
    }
  }
  if (hitAny) {
    game.fx.slash(player.x + player.facing * 30, player.z, player.facing, 54, player.comboStep === 2 ? 56 : 44)
    game.shake = Math.max(game.shake, attack.shake)
  }
}

function respawnPlayer(game, player) {
  player.hp = player.maxHp
  player.hpGhost = player.maxHp
  player.state = 'idle'
  player.stateT = 0
  player.attackP = 0
  player.comboStep = 0
  player.jumpY = 0
  player.vy = 0
  player.vx = 0
  player.vz = 0
  player.downP = 0
  player.iframes = 2.6
  player.special = 0
  player.z = 0.62
  player.x = clamp(game.camera.x + 190, game.camera.x + 60, game.camera.x + VIEW_W - 90)

  for (const enemy of game.enemies) {
    if (enemy.dead) continue
    enemy.state = 'idle'
    enemy.stateT = 0
    enemy.attackP = 0
    enemy.didHit = false
    enemy.attackCooldown = 1.3
    enemy.x += enemy.x > player.x ? 46 : -46
    if (enemy.kind === 'boss') enemy.x = clamp(enemy.x, game.camera.x + 80, game.camera.x + VIEW_W - 80)
  }

  game.fx.ring(player.x, player.z, 130, '255, 220, 140', 0.6, 0.24)
  game.fx.dust(player.x, player.z, 12)
  game.audio.sfx('clear')
  game.showBanner?.('GET UP!', `${player.lives} CLUBS LEFT`, {
    size: 52,
    color: '#ffe08a',
    duration: 1.8,
  })
}

export function updatePlayer(game, dt) {
  const player = game.player
  const input = game.input
  player.animT += dt

  if (player.hitFlash > 0) player.hitFlash -= dt
  if (player.iframes > 0) player.iframes -= dt
  player.attackBuffer = Math.max(0, player.attackBuffer - dt)

  if (player.hpGhost > player.hp) {
    player.hpGhost = Math.max(player.hp, player.hpGhost - 42 * dt)
  } else {
    player.hpGhost = player.hp
  }

  if (player.state === 'down') {
    player.stateT += dt
    player.downP = Math.min(1, player.stateT / 0.5)
    player.downTimer -= dt
    player.jumpY = 0
    player.vy = 0
    if (player.downTimer <= 0) {
      if (player.lives > 0) respawnPlayer(game, player)
      else game.onPlayerDefeat?.()
    }
    return
  }

  if (player.state === 'hurt') {
    player.stateT += dt
    player.x += player.vx * dt
    player.z = clamp(player.z + player.vz * dt, 0, 1)
    player.vx *= 0.86
    player.vz *= 0.9
    playerBounds(game, player)
    if (player.stateT > 0.34) {
      player.state = player.jumpY > 0 ? 'jump' : 'idle'
      player.stateT = 0
    }
    return
  }

  // jump physics
  if (player.jumpY > 0 || player.vy > 0) {
    player.jumpY += player.vy * dt
    player.vy -= GRAVITY * dt
    if (player.jumpY <= 0) {
      player.jumpY = 0
      player.vy = 0
      if (player.state === 'jump') {
        player.state = 'idle'
        game.audio.sfx('land')
        game.fx.dust(player.x, player.z, 6)
        game.shake = Math.max(game.shake, 1.8)
      }
    }
  }

  if (player.state === 'special') {
    player.stateT += dt
    player.attackP = clamp(player.stateT / 0.86, 0, 1)
    if (!player.didBlast && player.stateT > 0.27) {
      player.didBlast = true
      const blastRadius = 238
      for (const enemy of game.enemies) {
        if (enemy.dead) continue
        if (Math.abs(enemy.x - player.x) < blastRadius && Math.abs(enemy.z - player.z) < 0.58) {
          damageEnemy(game, enemy, 34, 340, Math.sign(enemy.x - player.x) || 1)
        }
      }
      game.fx.ring(player.x, player.z, blastRadius, '255, 205, 93', 0.55, 0.24)
      game.fx.ring(player.x, player.z, blastRadius * 0.65, '255, 120, 52', 0.42, 0.3)
      game.fx.impact(player.x, player.z, 58, 2.2, '255, 214, 110')
      game.fx.text('RAAAWR!', player.x, player.z, '#ffe08a', 36, { height: 105, life: 1 })
      game.shake = Math.max(game.shake, 18)
      game.hitstop = Math.max(game.hitstop, 0.1)
      game.audio.sfx('special')
    }
    if (player.stateT > 0.86) {
      player.state = player.jumpY > 0 ? 'jump' : 'idle'
      player.stateT = 0
      player.attackP = 0
    }
    playerBounds(game, player)
    return
  }

  if (player.state === 'attack') {
    const attack = ATTACKS[player.comboStep] || ATTACKS[0]
    player.attackT += dt
    player.attackP = clamp(player.attackT / player.attackDur, 0, 1)
    if (player.attackP < 0.55) player.x += player.facing * 56 * dt
    if (!player.didHit && player.attackP >= attack.hitAt) {
      player.didHit = true
      playerHitCheck(game)
    }
    if (input.consume('attack')) player.attackBuffer = 1
    if (player.attackP >= 1) {
      if (player.attackBuffer && player.comboStep < ATTACKS.length - 1) {
        startAttack(game, player.comboStep + 1)
      } else {
        player.state = player.jumpY > 0 ? 'jump' : 'idle'
        player.stateT = 0
        player.attackP = 0
        player.comboStep = 0
        player.attackBuffer = 0
      }
    }
    playerBounds(game, player)
    return
  }

  const jumpPressed = input.consume('jump')
  const attackPressed = input.consume('attack')
  const specialPressed = input.consume('special')
  const grounded = player.jumpY <= 0 && player.vy <= 0

  if (grounded && jumpPressed) {
    player.vy = JUMP_SPEED
    player.jumpY = 0.01
    player.state = 'jump'
    game.audio.sfx('jump')
    game.fx.dust(player.x, player.z, 5)
  }

  if (grounded && attackPressed) {
    player.stateT = 0
    startAttack(game, 0)
    return
  }

  if (grounded && specialPressed && player.special >= 100) {
    startSpecial(game)
    return
  }

  const ax = input.ax
  const az = input.az
  const moving = Math.hypot(ax, az) > 0.12

  if (moving) {
    const speed = grounded ? PLAYER_SPEED : PLAYER_SPEED * 0.78
    const length = Math.max(1, Math.hypot(ax, az))
    player.x += (ax / length) * speed * dt
    player.z += (az / length) * PLAYER_Z_SPEED * dt * (grounded ? 1 : 0.78)
    if (Math.abs(ax) > 0.15) player.facing = ax > 0 ? 1 : -1
    if (grounded && player.state !== 'walk') {
      player.state = 'walk'
      player.animT = 0
    }
    if (grounded) {
      player.stepTimer -= dt
      if (player.stepTimer <= 0) {
        player.stepTimer = 0.19
        game.fx.dust(player.x - player.facing * 10, player.z, 2, { color: '192, 148, 100' })
      }
    }
  } else if (grounded) {
    player.state = 'idle'
  }

  if (!grounded) player.state = 'jump'
  playerBounds(game, player)
}

/* ------------------------------------------------------------------ */
/* Enemies                                                             */
/* ------------------------------------------------------------------ */

export function damagePlayer(game, amount, sourceX) {
  const player = game.player
  if (player.state === 'down' || player.state === 'special' || player.iframes > 0 || game.state !== 'playing') return

  player.hp = Math.max(0, player.hp - amount)
  player.iframes = 0.95
  player.hitFlash = 0.16
  player.state = 'hurt'
  player.stateT = 0
  player.attackP = 0
  player.comboStep = 0
  player.attackBuffer = 0
  player.didHit = false
  player.vx = (player.x >= sourceX ? 1 : -1) * 195
  player.vz = rand(-0.05, 0.05)

  game.combo = 0
  game.comboTimer = 0
  game.comboPulse = 0
  game.shake = Math.max(game.shake, amount >= 20 ? 13 : 8)
  game.flash = 0.55
  game.hitstop = Math.max(game.hitstop, 0.06)
  game.audio.sfx('hurt')
  game.fx.impact(player.x, player.z, 56, 1.2, '255, 116, 68')
  game.fx.text('OUCH!', player.x, player.z, '#ff8a5b', 22, { height: 96 })

  if (player.hp <= 0) {
    player.hp = 0
    player.state = 'down'
    player.stateT = 0
    player.downP = 0
    player.downTimer = 1.7
    player.lives = Math.max(0, player.lives - 1)
    game.combo = 0
    game.shake = 16
    game.audio.sfx('gameover')
  }
}

export function damageEnemy(game, enemy, amount, knock, dir) {
  if (enemy.dead) return
  const multiplier = comboMultiplier(game.combo)
  enemy.hp -= amount
  enemy.hitFlash = 0.14
  enemy.attackP = 0

  const height = (enemy.jumpY || 0) + 52
  game.fx.impact(enemy.x, enemy.z, height, amount >= 18 ? 1.55 : 1, '255, 208, 93')
  if (Math.random() > 0.5) game.fx.bones(enemy.x, enemy.z, height - 8, 1)
  game.hitstop = Math.max(game.hitstop, amount >= 18 ? 0.085 : 0.05)
  game.shake = Math.max(game.shake, amount >= 18 ? 8 : 4)
  game.audio.sfx(amount >= 18 ? 'heavy' : 'hit')

  game.combo += 1
  game.comboTimer = 2.2
  game.comboPulse = 0.3
  game.maxCombo = Math.max(game.maxCombo, game.combo)
  game.score += Math.round(7 * multiplier)
  game.player.special = Math.min(100, game.player.special + (amount >= 18 ? 12 : 7))

  if (game.combo % 3 === 0 || amount >= 18) {
    game.fx.text(pickWord(), enemy.x, enemy.z, '#ffcf4d', amount >= 18 ? 29 : 20, { height: 94 })
  }

  if (enemy.hp <= 0) {
    killEnemy(game, enemy, dir)
    return
  }

  if (enemy.kind === 'boss') {
    if (!enemy.enraged && enemy.hp < enemy.maxHp * 0.45) {
      enemy.enraged = true
      game.onBossEnrage?.(enemy)
    }
    return
  }

  enemy.state = 'hurt'
  enemy.stateT = 0
  enemy.hurtT = 0.34
  enemy.jumpY = 0
  enemy.vy = 0
  enemy.vx = dir * knock
  enemy.vz = rand(-0.055, 0.055)
}

function killEnemy(game, enemy, dir) {
  enemy.hp = 0
  enemy.dead = true
  enemy.state = 'down'
  enemy.stateT = 0
  enemy.downP = 0
  enemy.deadT = 0
  enemy.jumpY = 0
  enemy.vy = 0
  enemy.vx = dir * 260
  enemy.vz = rand(-0.1, 0.1)
  enemy.alpha = 1

  const multiplier = comboMultiplier(game.combo)
  const points = Math.round((enemy.scoreValue || 100) * multiplier)
  game.score += points
  game.fx.text(`+${points}`, enemy.x, enemy.z, '#ffe08a', 23, { height: 76, life: 0.95 })
  game.fx.bones(enemy.x, enemy.z, 28, enemy.kind === 'boss' ? 14 : 4)
  game.fx.ring(enemy.x, enemy.z, enemy.kind === 'boss' ? 260 : 46, '255, 211, 120', enemy.kind === 'boss' ? 0.7 : 0.3, 0.24)
  game.audio.sfx('heavy')
  game.comboPulse = 0.25

  if (enemy.kind === 'boss') {
    game.onBossDefeated?.(enemy)
  } else if (enemy.kind === 'clubber' && Math.random() < 0.55) {
    game.dropPickup?.(enemy.x, enemy.z)
  }
}

function updateDead(enemy, dt) {
  enemy.deadT += dt
  if (enemy.downP < 1) enemy.downP = Math.min(1, enemy.deadT / 0.45)
  enemy.x += enemy.vx * dt
  enemy.z = clamp(enemy.z + enemy.vz * dt, 0, 1)
  enemy.vx *= 0.9
  enemy.vz *= 0.9
  if (enemy.kind !== 'boss') {
    if (enemy.deadT > 1.2) enemy.alpha = clamp(1 - (enemy.deadT - 1.2) / 0.55, 0, 1)
    if (enemy.deadT > 1.8) enemy.remove = true
  }
}

function enemyStrike(game, enemy) {
  const player = game.player
  if (player.state === 'down' || game.state !== 'playing') return
  const dx = (player.x - enemy.x) * enemy.facing
  const depth = Math.abs(player.z - enemy.z)
  if (dx > -24 && dx < enemy.range + 30 && depth < 0.22 && player.jumpY < 34) {
    damagePlayer(game, enemy.damage, enemy.x)
  }
}

function startLeap(game, enemy) {
  const player = game.player
  enemy.state = 'leap'
  enemy.stateT = 0
  enemy.leapFrom = { x: enemy.x, z: enemy.z }
  enemy.leapTo = {
    x: clamp(player.x + player.vx * 0.14, game.camera.x + 40, game.camera.x + VIEW_W - 40),
    z: clamp(player.z, 0.02, 0.98),
  }
  enemy.jumpY = 1
  enemy.didHit = false
  game.audio.sfx('swing')
}

function updateLeaper(game, enemy, dt) {
  const player = game.player

  if (enemy.state === 'leapWind') {
    enemy.stateT += dt
    enemy.facing = player.x >= enemy.x ? 1 : -1
    if (enemy.stateT > 0.42) startLeap(game, enemy)
    return
  }

  if (enemy.state === 'leap') {
    enemy.stateT += dt
    const t = clamp(enemy.stateT / 0.62, 0, 1)
    enemy.x = enemy.leapFrom.x + (enemy.leapTo.x - enemy.leapFrom.x) * t
    enemy.z = enemy.leapFrom.z + (enemy.leapTo.z - enemy.leapFrom.z) * t
    enemy.jumpY = Math.sin(Math.PI * t) * 84
    if (t >= 1) {
      enemy.jumpY = 0
      enemy.state = 'idle'
      enemy.stateT = 0
      enemy.attackCooldown = rand(1.05, 1.5)
      game.fx.dust(enemy.x, enemy.z, 10)
      game.fx.ring(enemy.x, enemy.z, 54, '224, 176, 116', 0.32, 0.24)
      game.audio.sfx('land')
      const dx = (player.x - enemy.x) * enemy.facing
      const depth = Math.abs(player.z - enemy.z)
      if (dx > -36 && dx < 96 && depth < 0.25 && player.jumpY < 46) {
        damagePlayer(game, enemy.damage, enemy.x)
      }
    }
    return
  }

  if (enemy.state === 'hurt') {
    enemy.stateT += dt
    enemy.x += enemy.vx * dt
    enemy.z = clamp(enemy.z + enemy.vz * dt, 0, 1)
    enemy.vx *= 0.85
    enemy.vz *= 0.9
    if (enemy.stateT > 0.32) enemy.state = 'idle'
    return
  }

  if (enemy.state === 'attack') {
    enemy.stateT += dt
    enemy.attackP = clamp(enemy.stateT / enemy.attackDuration, 0, 1)
    if (!enemy.didHit && enemy.attackP >= enemy.hitAt) {
      enemy.didHit = true
      enemyStrike(game, enemy)
    }
    if (enemy.attackP >= 1) {
      enemy.state = 'idle'
      enemy.stateT = 0
      enemy.attackP = 0
      enemy.attackCooldown = rand(...ENEMY_STATS.leaper.cooldown)
    }
    return
  }

  if (enemy.state === 'spawn') {
    enemy.stateT += dt
    if (enemy.stateT > 0.45) {
      enemy.state = 'idle'
      enemy.stateT = 0
    }
    return
  }

  if (player.state === 'down' || game.state !== 'playing') {
    enemy.state = 'idle'
    return
  }

  const dx = player.x - enemy.x
  const depth = Math.abs(player.z - enemy.z)
  enemy.facing = dx >= 0 ? 1 : -1

  if (Math.abs(dx) > 105 && Math.abs(dx) < 330 && depth < 0.26 && enemy.attackCooldown <= 0) {
    enemy.state = 'leapWind'
    enemy.stateT = 0
    game.fx.dust(enemy.x, enemy.z, 4)
    return
  }

  if (Math.abs(dx) < enemy.range && depth < 0.17 && enemy.attackCooldown <= 0) {
    enemy.state = 'attack'
    enemy.stateT = 0
    enemy.attackP = 0
    enemy.didHit = false
    return
  }

  const side = enemy.x >= player.x ? 1 : -1
  const targetX = player.x + side * enemy.range * 0.8
  const targetZ = clamp(player.z + enemy.slotOffset, 0.05, 0.95)
  const moveX = targetX - enemy.x
  const moveZ = targetZ - enemy.z
  if (Math.abs(moveX) > 4 || Math.abs(moveZ) > 0.014) {
    const speed = enemy.speed * (Math.abs(dx) > 360 ? 1.35 : 1)
    const vx = moveX
    const vz = moveZ * 150
    const length = Math.max(1, Math.hypot(vx, vz))
    enemy.x += (vx / length) * speed * dt
    enemy.z += ((vz / length) * speed * dt) / 150
    enemy.z = clamp(enemy.z, 0, 1)
    enemy.state = 'walk'
    enemy.stepTimer -= dt
    if (enemy.stepTimer <= 0) {
      enemy.stepTimer = 0.24
      game.fx.dust(enemy.x - enemy.facing * 8, enemy.z, 1, { color: '176, 132, 88' })
    }
  } else {
    enemy.state = 'idle'
  }
}

export function updateEnemy(game, enemy, dt) {
  enemy.animT += dt
  if (enemy.hitFlash > 0) enemy.hitFlash -= dt
  if (enemy.attackCooldown > 0) enemy.attackCooldown -= dt
  if (enemy.hpGhost > enemy.hp) enemy.hpGhost = Math.max(enemy.hp, enemy.hpGhost - 60 * dt)

  if (enemy.dead) {
    updateDead(enemy, dt)
    return
  }

  if (enemy.kind === 'boss') {
    updateBoss(game, enemy, dt)
  } else if (enemy.kind === 'leaper') {
    updateLeaper(game, enemy, dt)
  } else {
    updateGrunt(game, enemy, dt)
  }
}

function updateGrunt(game, enemy, dt) {
  const player = game.player

  if (enemy.state === 'spawn') {
    enemy.stateT += dt
    if (enemy.stateT > 0.45) {
      enemy.state = 'idle'
      enemy.stateT = 0
    }
    return
  }

  if (enemy.state === 'hurt') {
    enemy.stateT += dt
    enemy.x += enemy.vx * dt
    enemy.z = clamp(enemy.z + enemy.vz * dt, 0, 1)
    enemy.vx *= 0.85
    enemy.vz *= 0.9
    if (enemy.stateT > 0.32) enemy.state = 'idle'
    return
  }

  if (enemy.state === 'attack') {
    enemy.stateT += dt
    enemy.attackP = clamp(enemy.stateT / enemy.attackDuration, 0, 1)
    if (!enemy.didHit && enemy.attackP >= enemy.hitAt) {
      enemy.didHit = true
      enemyStrike(game, enemy)
      game.audio.sfx('swing')
    }
    if (enemy.attackP >= 1) {
      enemy.state = 'idle'
      enemy.stateT = 0
      enemy.attackP = 0
      enemy.attackCooldown = rand(...ENEMY_STATS[enemy.kind].cooldown)
    }
    return
  }

  if (player.state === 'down' || game.state !== 'playing') {
    enemy.state = 'idle'
    return
  }

  const dx = player.x - enemy.x
  const depth = Math.abs(player.z - enemy.z)
  enemy.facing = dx >= 0 ? 1 : -1

  if (Math.abs(dx) < enemy.range && depth < 0.17 && enemy.attackCooldown <= 0) {
    enemy.state = 'attack'
    enemy.stateT = 0
    enemy.attackP = 0
    enemy.didHit = false
    return
  }

  const side = enemy.x >= player.x ? 1 : -1
  const targetX = player.x + side * enemy.range * 0.78
  const targetZ = clamp(player.z + enemy.slotOffset, 0.05, 0.95)
  const moveX = targetX - enemy.x
  const moveZ = targetZ - enemy.z
  if (Math.abs(moveX) > 4 || Math.abs(moveZ) > 0.014) {
    const speed = enemy.speed * (Math.abs(dx) > 360 ? 1.35 : 1)
    const vx = moveX
    const vz = moveZ * 150
    const length = Math.max(1, Math.hypot(vx, vz))
    enemy.x += (vx / length) * speed * dt
    enemy.z += ((vz / length) * speed * dt) / 150
    enemy.z = clamp(enemy.z, 0, 1)
    enemy.state = 'walk'
    enemy.stepTimer -= dt
    if (enemy.stepTimer <= 0) {
      enemy.stepTimer = 0.26
      game.fx.dust(enemy.x - enemy.facing * 8, enemy.z, 1, { color: '176, 132, 88' })
    }
  } else {
    enemy.state = 'idle'
  }
}

/* ------------------------------------------------------------------ */
/* Boss                                                                */
/* ------------------------------------------------------------------ */

function bossStart(game, boss, state) {
  boss.state = state
  boss.stateT = 0
  boss.didHit = false
  if (state === 'slamWind') {
    boss.slamTarget = {
      x: clamp(game.player.x, game.camera.x + 80, game.camera.x + VIEW_W - 80),
      z: clamp(game.player.z, 0.12, 0.92),
    }
    boss.slamFrom = { x: boss.x, z: boss.z }
    game.audio.sfx('roar')
  } else if (state === 'chargeWind') {
    game.audio.sfx('charge')
  } else if (state === 'swingWind') {
    game.audio.sfx('swing')
  }
}

function chooseBossAttack(game, boss) {
  const player = game.player
  const distance = Math.abs(player.x - boss.x)
  const pattern = boss.pattern % 4
  boss.pattern += 1
  boss.facing = player.x >= boss.x ? 1 : -1

  if (distance > 300) {
    bossStart(game, boss, pattern === 2 ? 'slamWind' : 'chargeWind')
  } else if (distance < 195) {
    bossStart(game, boss, pattern === 3 ? 'slamWind' : 'swingWind')
  } else {
    bossStart(game, boss, pattern % 2 === 0 ? 'swingWind' : 'slamWind')
  }
}

function bossSwingHit(game, boss) {
  const player = game.player
  game.fx.slash(boss.x + boss.facing * 62, boss.z, boss.facing, 72, 66)
  game.shake = Math.max(game.shake, 10)
  game.audio.sfx('heavy')
  if (player.state === 'down') return
  const dx = (player.x - boss.x) * boss.facing
  const depth = Math.abs(player.z - boss.z)
  if (dx > -34 && dx < 158 && depth < 0.3 && player.jumpY < 42) {
    damagePlayer(game, 18, boss.x)
  }
}

function bossSlam(game, boss) {
  const target = boss.slamTarget || { x: boss.x, z: boss.z }
  game.fx.ring(target.x, target.z, 242, '255, 152, 59', 0.52, 0.3)
  game.fx.ring(target.x, target.z, 120, '255, 214, 130', 0.34, 0.3)
  game.fx.dust(target.x, target.z, 18)
  game.fx.debris(target.x, target.z, 8, 8)
  game.shake = Math.max(game.shake, 17)
  game.hitstop = Math.max(game.hitstop, 0.06)
  game.audio.sfx('slam')

  const player = game.player
  if (player.state === 'down') return
  if (Math.abs(player.x - target.x) < 242 && Math.abs(player.z - target.z) < 0.52 && player.jumpY < 30) {
    damagePlayer(game, 24, target.x)
  }
}

function updateBoss(game, boss, dt) {
  const player = game.player

  if (boss.state === 'intro') {
    boss.stateT += dt
    boss.facing = -1
    boss.x -= 52 * dt
    boss.stepTimer -= dt
    if (boss.stepTimer <= 0) {
      boss.stepTimer = 0.22
      game.fx.dust(boss.x - 8, boss.z, 2, { color: '186, 140, 92' })
    }
    if (boss.stateT > 1.7) {
      boss.state = 'idle'
      boss.stateT = 0
      boss.attackCooldown = 0.65
    }
    return
  }

  if (boss.state === 'swingWind') {
    boss.stateT += dt
    if (boss.stateT > (boss.enraged ? 0.5 : 0.66)) {
      boss.state = 'swingHit'
      boss.stateT = 0
      bossSwingHit(game, boss)
    }
    return
  }

  if (boss.state === 'swingHit') {
    boss.stateT += dt
    if (boss.stateT > 0.26) {
      boss.state = 'idle'
      boss.stateT = 0
      boss.attackCooldown = boss.enraged ? 0.42 : 0.8
    }
    return
  }

  if (boss.state === 'slamWind') {
    boss.stateT += dt
    if (boss.stateT > (boss.enraged ? 0.58 : 0.78)) {
      boss.state = 'slamAir'
      boss.stateT = 0
      boss.jumpY = 1
      boss.slamFrom = { x: boss.x, z: boss.z }
    }
    return
  }

  if (boss.state === 'slamAir') {
    boss.stateT += dt
    const duration = 0.62
    const t = clamp(boss.stateT / duration, 0, 1)
    const target = boss.slamTarget
    if (target) {
      boss.x = boss.slamFrom.x + (target.x - boss.slamFrom.x) * t
      boss.z = boss.slamFrom.z + (target.z - boss.slamFrom.z) * t
    }
    boss.jumpY = Math.sin(Math.PI * t) * 112
    if (t >= 1) {
      boss.jumpY = 0
      boss.state = 'slamLand'
      boss.stateT = 0
      bossSlam(game, boss)
    }
    return
  }

  if (boss.state === 'slamLand') {
    boss.stateT += dt
    if (boss.stateT > 0.52) {
      boss.state = 'idle'
      boss.stateT = 0
      boss.attackCooldown = boss.enraged ? 0.55 : 0.95
    }
    return
  }

  if (boss.state === 'chargeWind') {
    boss.stateT += dt
    if (boss.stateT > (boss.enraged ? 0.42 : 0.58)) {
      boss.state = 'charge'
      boss.stateT = 0
      boss.didHit = false
      boss.vx = boss.facing * (boss.enraged ? 640 : 540)
    }
    return
  }

  if (boss.state === 'charge') {
    boss.stateT += dt
    boss.x += boss.vx * dt
    boss.x = clamp(boss.x, game.camera.x + 60, game.camera.x + VIEW_W - 60)
    boss.stepTimer -= dt
    if (boss.stepTimer <= 0) {
      boss.stepTimer = 0.08
      game.fx.dust(boss.x - boss.facing * 18, boss.z, 2, { color: '194, 146, 94' })
    }
    if (!boss.didHit && player.state !== 'down') {
      const dx = (player.x - boss.x) * boss.facing
      const depth = Math.abs(player.z - boss.z)
      if (dx > -50 && dx < 92 && depth < 0.25 && player.jumpY < 34) {
        boss.didHit = true
        damagePlayer(game, 22, boss.x)
        game.shake = Math.max(game.shake, 12)
      }
    }
    if (boss.stateT > 0.58) {
      boss.state = 'chargeRec'
      boss.stateT = 0
    }
    return
  }

  if (boss.state === 'chargeRec') {
    boss.stateT += dt
    if (boss.stateT > 0.75) {
      boss.state = 'idle'
      boss.stateT = 0
      boss.attackCooldown = boss.enraged ? 0.4 : 0.7
    }
    return
  }

  if (boss.state === 'hurt') {
    boss.stateT += dt
    boss.x += boss.vx * dt
    boss.vx *= 0.85
    if (boss.stateT > 0.3) boss.state = 'idle'
    return
  }

  // idle / walk
  boss.stateT += dt
  if (player.state === 'down' || game.state !== 'playing') {
    boss.state = 'idle'
    return
  }

  boss.facing = player.x >= boss.x ? 1 : -1
  const distance = Math.abs(player.x - boss.x)
  const depth = Math.abs(player.z - boss.z)
  const side = boss.x >= player.x ? 1 : -1
  const targetX = player.x + side * 158
  const targetZ = clamp(player.z, 0.15, 0.9)
  const moveX = targetX - boss.x
  const moveZ = targetZ - boss.z

  if (Math.abs(moveX) > 12 || Math.abs(moveZ) > 0.03) {
    const speed = boss.speed * (boss.enraged ? 1.28 : 1)
    const vx = moveX
    const vz = moveZ * 150
    const length = Math.max(1, Math.hypot(vx, vz))
    boss.x += (vx / length) * speed * dt
    boss.z += ((vz / length) * speed * dt) / 150
    boss.x = clamp(boss.x, game.camera.x + 70, game.camera.x + VIEW_W - 70)
    boss.z = clamp(boss.z, 0.12, 0.92)
    boss.state = 'walk'
    boss.stepTimer -= dt
    if (boss.stepTimer <= 0) {
      boss.stepTimer = 0.2
      game.fx.dust(boss.x - boss.facing * 10, boss.z, 2, { color: '186, 140, 92' })
    }
  } else {
    boss.state = 'idle'
  }

  if (distance < 430 && boss.attackCooldown <= 0) chooseBossAttack(game, boss)
}

import { Input } from './input.js'
import { AudioEngine } from './audio.js'
import { FX } from './fx.js'
import {
  createPlayer, createEnemy, updatePlayer, updateEnemy,
} from './actors.js'
import {
  VIEW_W, VIEW_H, GROUND_TOP, DEPTH, LEVEL_END, WAVES, WAVE_COUNT, FIXED_PICKUPS,
} from './config.js'
import {
  drawBackground, drawForeground, drawCharacter, drawMeat,
  drawHUD, drawBanner, drawVignette,
} from './art.js'

const canvas = document.getElementById('game')
const ctx = canvas.getContext('2d')
const input = new Input()
const audio = new AudioEngine()
const fx = new FX()

const screens = {
  title: document.getElementById('screen-title'),
  pause: document.getElementById('screen-pause'),
  over: document.getElementById('screen-over'),
  win: document.getElementById('screen-win'),
}
const muteButton = document.getElementById('mute-btn')

const HIGH_SCORE_KEY = 'wammer-dudes.highscore'
const MUTE_KEY = 'wammer-dudes.muted'

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function rand(min, max) {
  return min + Math.random() * (max - min)
}

function loadHighScore() {
  try {
    return Math.max(0, Number(localStorage.getItem(HIGH_SCORE_KEY)) || 0)
  } catch {
    return 0
  }
}

function saveHighScore(score) {
  try {
    localStorage.setItem(HIGH_SCORE_KEY, String(Math.floor(score)))
  } catch {
    // private mode: score simply won't persist
  }
}

function storedMute() {
  try {
    return localStorage.getItem(MUTE_KEY) === '1'
  } catch {
    return false
  }
}

const game = {
  state: 'title',
  time: 0,
  dt: 0,
  input,
  audio,
  fx,
  player: createPlayer(),
  enemies: [],
  pickups: [],
  waves: [],
  waveIndex: -1,
  activeWave: null,
  boss: null,
  camera: { x: 0, shake: 0, lock: null },
  score: 0,
  highScore: loadHighScore(),
  combo: 0,
  comboTimer: 0,
  comboPulse: 0,
  maxCombo: 0,
  banner: null,
  hitstop: 0,
  flash: 0,
  victoryTimer: 0,
  titleCam: 240,
  titleRival: null,
  dropCount: 0,
}

audio.muted = storedMute()

function refreshMuteButton() {
  muteButton.classList.toggle('muted', audio.muted)
  muteButton.setAttribute('aria-label', audio.muted ? 'Unmute sound' : 'Mute sound')
}

function toggleMute(force) {
  const muted = audio.toggleMute(force)
  refreshMuteButton()
  try {
    localStorage.setItem(MUTE_KEY, muted ? '1' : '0')
  } catch {
    // ignore storage failures
  }
}

function padScore(value) {
  return String(Math.max(0, Math.floor(value))).padStart(6, '0')
}

function refreshOverlays() {
  const best = Math.max(game.highScore, game.score)
  document.getElementById('hs-title').textContent = padScore(best)
  document.getElementById('final-score').textContent = padScore(game.score)
  document.getElementById('best-score').textContent = padScore(best)
  document.getElementById('win-score').textContent = padScore(game.score)
  document.getElementById('win-best').textContent = padScore(best)
}

function showScreen(name) {
  for (const [key, element] of Object.entries(screens)) {
    element.classList.toggle('hidden', key !== name)
  }
  if (document.activeElement instanceof HTMLElement) document.activeElement.blur()
}

function makeWaves() {
  return WAVES.map((wave) => ({ ...wave, enemies: [...wave.enemies] }))
}

function showBanner(title, sub, options = {}) {
  const duration = options.duration ?? 2
  game.banner = {
    title,
    sub,
    t: duration,
    duration,
    size: options.size ?? 56,
    color: options.color ?? '#ffcf4d',
    y: options.y ?? 172,
    rotate: options.rotate ?? -0.025,
    strokeWidth: options.strokeWidth ?? 9,
  }
}

function resetRun() {
  game.player = createPlayer()
  game.enemies.length = 0
  game.pickups = FIXED_PICKUPS.map((pickup) => ({ ...pickup }))
  game.waves = makeWaves()
  game.waveIndex = -1
  game.activeWave = null
  game.boss = null
  game.camera.x = 0
  game.camera.shake = 0
  game.camera.lock = null
  game.score = 0
  game.combo = 0
  game.comboTimer = 0
  game.comboPulse = 0
  game.maxCombo = 0
  game.hitstop = 0
  game.flash = 0
  game.victoryTimer = 0
  game.dropCount = 0
  game.time = 0
  game.titleCam = 240
  fx.reset()
  audio.setScene('fight')
  showBanner('FIRE VALLEY', 'SMASH RIGHT TO FIND THE BONEFANG', {
    size: 54,
    duration: 2.7,
    y: 176,
  })
}

function beginRun() {
  audio.unlock()
  if (audio.muted) audio.toggleMute(true)
  resetRun()
  game.state = 'playing'
  showScreen(null)
  audio.sfx('clear')
}

function pauseGame() {
  if (game.state !== 'playing') return
  game.state = 'paused'
  showScreen('pause')
}

function resumeGame() {
  if (game.state !== 'paused') return
  game.state = 'playing'
  showScreen(null)
}

function finishRun(won) {
  if (game.state === 'gameover' || game.state === 'victory') return
  game.state = won ? 'victory' : 'gameover'
  if (game.score > game.highScore) {
    game.highScore = Math.floor(game.score)
    saveHighScore(game.highScore)
  }
  refreshOverlays()
  showScreen(won ? 'win' : 'over')
  audio.setScene('title')
  if (won) audio.sfx('win')
}

function onPlayerDefeat() {
  if (game.state !== 'playing') return
  finishRun(false)
}

function onBossDefeated(boss) {
  game.boss = null
  game.camera.lock = null
  game.activeWave = null
  game.victoryTimer = 3.15
  game.score += 2500
  game.camera.shake = 22
  game.hitstop = 0.12
  fx.text('MOG DOWN!', boss.x, boss.z, '#ffcf4d', 44, { height: 128, life: 2.2 })
  fx.ring(boss.x, boss.z, 320, '255, 214, 120', 0.9, 0.26)
  showBanner('MAMMOTH MOG FALLS', 'THE VALLEY IS YOURS', {
    size: 46,
    color: '#ffe08a',
    duration: 3,
    y: 168,
  })
  audio.sfx('roar')
}

function onBossEnrage(boss) {
  game.camera.shake = Math.max(game.camera.shake, 14)
  fx.ring(boss.x, boss.z, 180, '255, 113, 52', 0.6, 0.3)
  fx.text('ENRAGED!', boss.x, boss.z, '#ff8a5b', 34, { height: 126, life: 1.4 })
  audio.sfx('roar')
  showBanner('MOG IS FURIOUS', 'JUMP OVER THE GROUND SLAM', {
    size: 34,
    color: '#ff8a5b',
    duration: 1.8,
    y: 140,
  })
}

function dropPickup(x, z) {
  if (game.pickups.length > 5) return
  game.dropCount += 1
  game.pickups.push({
    x: clamp(x, 40, LEVEL_END - 40),
    z: clamp(z, 0.08, 0.94),
    seed: rand(0, 10),
  })
}

game.onPlayerDefeat = onPlayerDefeat
game.onBossDefeated = onBossDefeated
game.onBossEnrage = onBossEnrage
game.dropPickup = dropPickup
game.showBanner = showBanner

game.titleRival = createEnemy('grunt', 820, 0.72)
game.titleRival.state = 'idle'
game.titleRival.animT = 0

/* ------------------------------------------------------------------ */
/* Run flow                                                            */
/* ------------------------------------------------------------------ */

function startWave(index) {
  const wave = game.waves[index]
  if (!wave) return
  game.waveIndex = index
  game.camera.lock = wave.lock

  if (wave.boss) {
    game.activeWave = { index, lock: wave.lock, pending: [], boss: true, cleared: false }
    const boss = createEnemy('boss', wave.lock + 620, 0.68)
    boss.state = 'intro'
    boss.stateT = 0
    boss.facing = -1
    game.enemies.push(boss)
    game.boss = boss
    audio.setScene('boss')
    audio.sfx('roar')
    showBanner('MAMMOTH MOG', 'CHIEFTAIN OF THE BONEFANG', {
      size: 56,
      color: '#ff8a5b',
      duration: 2.9,
      y: 168,
      strokeWidth: 10,
    })
  } else {
    const pending = wave.enemies.map((type, i) => ({
      type,
      side: wave.flank && i === wave.enemies.length - 1 ? 'left' : 'right',
      delay: 0.15 + i * 0.42,
      slot: i,
    }))
    game.activeWave = { index, lock: wave.lock, pending, boss: false, cleared: false }
    showBanner(wave.name, `FIGHT ${index + 1} OF ${WAVE_COUNT}`, {
      size: 52,
      color: '#ffcf4d',
      duration: 1.9,
      y: 170,
    })
  }
}

function spawnWaveEnemy(spec) {
  const x = spec.side === 'left'
    ? game.camera.x - 60 - rand(0, 70)
    : game.camera.x + VIEW_W + 50 + rand(0, 110)
  const z = clamp(rand(0.16, 0.9), 0, 1)
  const enemy = createEnemy(spec.type, x, z, spec.slot)
  enemy.facing = spec.side === 'left' ? 1 : -1
  game.enemies.push(enemy)
  fx.dust(x, z, 5, { color: '188, 144, 96' })
}

function updateWaves(dt) {
  const active = game.activeWave
  if (active) {
    for (let i = active.pending.length - 1; i >= 0; i -= 1) {
      const spec = active.pending[i]
      spec.delay -= dt
      if (spec.delay <= 0) {
        spawnWaveEnemy(spec)
        active.pending.splice(i, 1)
      }
    }

    if (!active.cleared && !active.boss && active.pending.length === 0) {
      const anyAlive = game.enemies.some((enemy) => !enemy.dead)
      if (!anyAlive) {
        active.cleared = true
        game.activeWave = null
        game.camera.lock = null
        const bonus = 220 + game.waveIndex * 45
        game.score += bonus
        fx.text(`+${bonus}`, game.player.x, game.player.z, '#ffe08a', 24, { height: 110, life: 1 })
        showBanner('PATH CLEARED', 'GO RIGHT  →', {
          size: 48,
          color: '#ffe08a',
          duration: 1.8,
          y: 176,
        })
        audio.sfx('clear')
      }
    }
    return
  }

  const nextIndex = game.waveIndex + 1
  const next = game.waves[nextIndex]
  if (next && game.player.x >= next.trigger && game.player.state !== 'down') {
    startWave(nextIndex)
  }
}

function updatePickups() {
  const player = game.player
  for (let i = game.pickups.length - 1; i >= 0; i -= 1) {
    const pickup = game.pickups[i]
    if (Math.abs(pickup.x - player.x) < 40 && Math.abs(pickup.z - player.z) < 0.17 && player.jumpY < 34) {
      player.hp = Math.min(player.maxHp, player.hp + 30)
      player.hpGhost = player.hp
      game.score += 60
      fx.text('+30 MEAT', pickup.x, pickup.z, '#a8e06a', 22, { height: 80, life: 1 })
      fx.impact(pickup.x, pickup.z, 26, 0.8, '180, 224, 120')
      audio.sfx('meat')
      game.pickups.splice(i, 1)
    }
  }
}

function updateCamera(dt) {
  const maxCam = game.camera.lock ?? (LEVEL_END - VIEW_W)
  const desired = clamp(game.player.x - 370, 0, maxCam)
  game.camera.x += (desired - game.camera.x) * (1 - Math.exp(-6.5 * dt))
}

function updateTimers(dt) {
  if (game.combo > 0) {
    game.comboTimer -= dt
    if (game.comboTimer <= 0) {
      game.combo = 0
      game.comboTimer = 0
    }
  }
  game.comboPulse = Math.max(0, game.comboPulse - dt * 2.8)
  game.flash = Math.max(0, game.flash - dt * 2.1)
  game.camera.shake = Math.max(0, game.camera.shake - dt * 24)
  if (game.banner) {
    game.banner.t -= dt
    if (game.banner.t <= 0) game.banner = null
  }
  if (game.score > game.highScore) {
    game.highScore = Math.floor(game.score)
  }
}

function updateTitle(dt) {
  game.player.animT += dt
  game.player.state = 'idle'
  game.titleRival.animT += dt
  game.titleRival.state = 'idle'
  game.titleCam = 250 + Math.sin(game.time * 0.08) * 55
  fx.update(dt)
}

/* ------------------------------------------------------------------ */
/* Main loop                                                           */
/* ------------------------------------------------------------------ */

let lastTime = performance.now()

function tick(dt) {
  input.sample()
  game.dt = dt

  if (input.consume('mute')) toggleMute()

  if (game.state === 'paused') {
    if (input.consume('pause') || input.consume('confirm')) {
      resumeGame()
      audio.unlock()
    }
    return
  }

  game.time += dt
  updateTimers(dt)

  if (game.state === 'title') {
    updateTitle(dt)
    if (input.consume('confirm') || input.consume('attack') || input.consume('jump') || input.consume('restart')) {
      beginRun()
    }
    return
  }

  if (game.state === 'gameover' || game.state === 'victory') {
    fx.update(dt * 0.55)
    if (input.consume('confirm') || input.consume('jump') || input.consume('restart')) {
      beginRun()
    }
    return
  }

  if (game.state !== 'playing') return

  if (input.consume('pause')) {
    pauseGame()
    return
  }

  if (game.hitstop > 0) {
    game.hitstop -= dt
    fx.update(dt * 0.18)
    return
  }

  updatePlayer(game, dt)
  for (const enemy of game.enemies) updateEnemy(game, enemy, dt)
  game.enemies = game.enemies.filter((enemy) => !enemy.remove)
  updatePickups()
  updateWaves(dt)
  updateCamera(dt)
  fx.update(dt)

  if (game.victoryTimer > 0) {
    game.victoryTimer -= dt
    if (game.victoryTimer <= 0) finishRun(true)
  }
}

function drawSlamWarning(ctx, boss, cameraX, time) {
  if (!boss || !boss.slamTarget) return
  if (boss.state !== 'slamWind' && boss.state !== 'slamAir') return
  const x = boss.slamTarget.x - cameraX
  const y = GROUND_TOP + boss.slamTarget.z * DEPTH
  const pulse = 0.65 + Math.sin(time * 18) * 0.2
  const radius = 232
  ctx.save()
  ctx.globalAlpha = pulse * 0.8
  ctx.strokeStyle = 'rgba(255, 116, 55, 0.95)'
  ctx.lineWidth = 4
  ctx.setLineDash([16, 10])
  ctx.beginPath()
  ctx.ellipse(x, y, radius, radius * 0.24, 0, 0, Math.PI * 2)
  ctx.stroke()
  ctx.setLineDash([])
  ctx.globalAlpha = 0.13
  ctx.fillStyle = '#ff7a3c'
  ctx.beginPath()
  ctx.ellipse(x, y, radius, radius * 0.24, 0, 0, Math.PI * 2)
  ctx.fill()
  ctx.restore()
}

function drawEnemyTells(ctx, cameraX, time) {
  for (const enemy of game.enemies) {
    if (enemy.dead) continue
    const screenX = enemy.x - cameraX
    if (screenX < -80 || screenX > VIEW_W + 80) continue
    const groundY = GROUND_TOP + enemy.z * DEPTH
    const y = groundY - (enemy.jumpY || 0) - (enemy.kind === 'boss' ? 150 : 104)
    let show = false
    let size = 22
    if (enemy.state === 'attack' && enemy.attackP < 0.45) show = true
    if (enemy.kind === 'boss' && ['swingWind', 'slamWind', 'chargeWind'].includes(enemy.state)) {
      show = true
      size = 30
    }
    if (!show) continue
    const bounce = Math.sin(time * 14 + enemy.seed) * 3
    ctx.save()
    ctx.translate(screenX, y + bounce)
    ctx.font = `400 ${size}px "Bangers", "Arial Black", sans-serif`
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.lineJoin = 'round'
    ctx.lineWidth = Math.max(3, size * 0.2)
    ctx.strokeStyle = '#2a130b'
    ctx.strokeText('!', 0, 0)
    ctx.fillStyle = enemy.kind === 'boss' ? '#ff7a3b' : '#ffcf4d'
    ctx.fillText('!', 0, 0)
    ctx.restore()
  }
}

function drawCampfire(ctx, cameraX, time) {
  const x = cameraX + 330
  const y = GROUND_TOP + 0.52 * DEPTH
  ctx.save()

  const glow = ctx.createRadialGradient(x, y - 22, 4, x, y - 18, 130)
  glow.addColorStop(0, 'rgba(255, 171, 70, 0.38)')
  glow.addColorStop(0.4, 'rgba(255, 120, 40, 0.14)')
  glow.addColorStop(1, 'rgba(255, 90, 30, 0)')
  ctx.fillStyle = glow
  ctx.fillRect(x - 140, y - 150, 280, 210)

  // logs
  ctx.strokeStyle = '#3a2117'
  ctx.lineWidth = 10
  ctx.lineCap = 'round'
  ctx.beginPath()
  ctx.moveTo(x - 27, y + 4)
  ctx.lineTo(x + 27, y - 5)
  ctx.moveTo(x - 26, y - 5)
  ctx.lineTo(x + 28, y + 4)
  ctx.stroke()
  ctx.strokeStyle = '#6a3d24'
  ctx.lineWidth = 5
  ctx.beginPath()
  ctx.moveTo(x - 27, y + 4)
  ctx.lineTo(x + 27, y - 5)
  ctx.moveTo(x - 26, y - 5)
  ctx.lineTo(x + 28, y + 4)
  ctx.stroke()

  for (let i = 0; i < 4; i += 1) {
    const flicker = Math.sin(time * 9 + i * 2.3) * 4
    const height = 34 + i * 8 + flicker
    const width = 13 - i * 2
    ctx.beginPath()
    ctx.moveTo(x - width + i * 3, y - 2)
    ctx.quadraticCurveTo(x - width + flicker, y - height * 0.6, x + i * 3 - 2, y - height)
    ctx.quadraticCurveTo(x + width + flicker, y - height * 0.4, x + width + i * 3, y - 1)
    ctx.closePath()
    ctx.fillStyle = i < 2 ? '#ffcf4d' : '#ff7a32'
    ctx.globalAlpha = 0.85 - i * 0.12
    ctx.fill()
    ctx.globalAlpha = 1
  }
  ctx.beginPath()
  ctx.ellipse(x, y - 7, 8, 15, 0.1, 0, Math.PI * 2)
  ctx.fillStyle = 'rgba(255, 245, 190, 0.85)'
  ctx.fill()
  ctx.restore()
}

function render() {
  const dpr = Math.min(2, window.devicePixelRatio || 1)
  if (canvas.width !== Math.floor(VIEW_W * dpr) || canvas.height !== Math.floor(VIEW_H * dpr)) {
    canvas.width = Math.floor(VIEW_W * dpr)
    canvas.height = Math.floor(VIEW_H * dpr)
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, VIEW_W, VIEW_H)
  ctx.imageSmoothingEnabled = true

  const camera = game.camera
  const shakeX = (Math.random() * 2 - 1) * camera.shake
  const shakeY = (Math.random() * 2 - 1) * camera.shake * 0.65
  const cameraX = game.state === 'title' ? game.titleCam : camera.x

  ctx.save()
  ctx.translate(shakeX, shakeY)
  drawBackground(ctx, cameraX, game.time)

  if (game.state === 'title') {
    drawCampfire(ctx, cameraX, game.time)
    game.player.x = cameraX + 158
    game.player.z = 0.72
    game.player.facing = 1
    game.player.hp = game.player.maxHp
    game.player.hpGhost = game.player.maxHp
    game.titleRival.x = cameraX + 824
    game.titleRival.z = 0.72
    game.titleRival.facing = -1
    game.titleRival.hp = 40
    game.titleRival.maxHp = 40
    const titleEntities = [game.player, game.titleRival].sort((a, b) => a.z - b.z)
    for (const entity of titleEntities) drawCharacter(ctx, entity, cameraX, game.time)
    drawForeground(ctx, cameraX, game.time)
    ctx.restore()
    drawVignette(ctx)
    return
  }

  fx.drawGround(ctx, cameraX)
  drawSlamWarning(ctx, game.boss, cameraX, game.time)

  for (const pickup of game.pickups) drawMeat(ctx, pickup, cameraX, game.time)

  const entities = [...game.enemies, game.player].sort((a, b) => a.z - b.z)
  for (const entity of entities) drawCharacter(ctx, entity, cameraX, game.time)

  fx.draw(ctx, cameraX)
  drawEnemyTells(ctx, cameraX, game.time)
  drawForeground(ctx, cameraX, game.time)
  ctx.restore()

  drawVignette(ctx)

  if (game.flash > 0) {
    ctx.fillStyle = `rgba(190, 32, 20, ${game.flash * 0.34})`
    ctx.fillRect(0, 0, VIEW_W, VIEW_H)
  }

  if (game.state === 'playing' || game.state === 'paused' || game.state === 'victory') {
    drawHUD(ctx, game, game.time)
  }
  if (game.state === 'playing') drawBanner(ctx, game.banner, game.time)
}

function frame(now) {
  const dt = Math.min(0.034, Math.max(0, (now - lastTime) / 1000))
  lastTime = now
  tick(dt)
  input.endFrame()
  render()
  requestAnimationFrame(frame)
}

/* ------------------------------------------------------------------ */
/* Wiring                                                              */
/* ------------------------------------------------------------------ */

document.getElementById('start-btn').addEventListener('click', beginRun)
document.getElementById('resume-btn').addEventListener('click', resumeGame)
document.getElementById('retry-btn').addEventListener('click', beginRun)
document.getElementById('again-btn').addEventListener('click', beginRun)
muteButton.addEventListener('click', () => toggleMute())
refreshMuteButton()

addEventListener('pointerdown', () => {
  audio.unlock()
  if (audio.muted) audio.toggleMute(true)
})
addEventListener('keydown', () => {
  audio.unlock()
  if (audio.muted) audio.toggleMute(true)
})

document.addEventListener('visibilitychange', () => {
  if (document.hidden && game.state === 'playing') pauseGame()
})

addEventListener('resize', () => {
  // canvas backing store is handled on the next render
})

showScreen('title')
refreshOverlays()
requestAnimationFrame(frame)

