import { createPlayer, updatePlayer } from '/home/runner/work/PlayGround/PlayGround/src/actors.js'

function makeGame({ ax = 0, az = 0, attack = false } = {}) {
  let attackPending = attack
  const calls = []
  const game = {
    state: 'playing',
    camera: { x: 0 },
    player: createPlayer(),
    enemies: [],
    shake: 0,
    hitstop: 0,
    combo: 0,
    comboTimer: 0,
    comboPulse: 0,
    maxCombo: 0,
    score: 0,
    input: {
      ax,
      az,
      consume(action) {
        if (action === 'attack' && attackPending) {
          attackPending = false
          return true
        }
        return false
      },
    },
    audio: { sfx: (name) => calls.push(name) },
    fx: {
      dust() {}, impact() {}, slash() {}, ring() {}, text() {}, bones() {},
    },
  }
  return game
}

function step(game, frames, dt = 1 / 60) {
  for (let i = 0; i < frames; i += 1) updatePlayer(game, dt)
}

// 1. Grounded attack while holding right
{
  const game = makeGame({ ax: 1, attack: true })
  const startX = game.player.x
  step(game, 1)
  const first = { state: game.player.state, x: game.player.x, facing: game.player.facing }
  step(game, 10)
  const after = { state: game.player.state, x: game.player.x, p: game.player.attackP }
  console.log('ground moving attack:', {
    startX,
    firstX: +first.x.toFixed(2),
    state: first.state,
    facing: first.facing,
    xAfter11: +after.x.toFixed(2),
    delta: +(after.x - startX).toFixed(2),
    attackP: +after.p.toFixed(2),
  })
}

// 2. Air attack while holding right
{
  const game = makeGame({ ax: 1, attack: true })
  const p = game.player
  p.x = 700
  p.jumpY = 60
  p.vy = 120
  p.state = 'jump'
  const startX = p.x
  const startY = p.jumpY
  step(game, 1)
  const first = { state: p.state, jumpY: p.jumpY, x: p.x, attackP: p.attackP }
  step(game, 8)
  const air = { state: p.state, jumpY: p.jumpY, x: p.x, attackP: p.attackP }
  step(game, 60)
  console.log('air moving attack:', {
    startX,
    firstState: first.state,
    firstJumpY: +first.jumpY.toFixed(2),
    firstAttackP: +first.attackP.toFixed(2),
    airState: air.state,
    airJumpY: +air.jumpY.toFixed(2),
    airAttackP: +air.attackP.toFixed(2),
    deltaX: +(air.x - startX).toFixed(2),
    startY,
    landedState: p.state,
    landedJumpY: +p.jumpY.toFixed(2),
    finalX: +p.x.toFixed(2),
  })
}

// 3. Air attack with no movement input still swings
{
  const game = makeGame({ attack: true })
  const p = game.player
  p.jumpY = 40
  p.vy = 0
  p.state = 'jump'
  step(game, 1)
  console.log('air neutral attack:', { state: p.state, jumpY: +p.jumpY.toFixed(2), attackP: +p.attackP.toFixed(2) })
}
